args.code:
const colAppTabId = 787784100;
const datesText = await browserjs(colAppTabId, async () => {
  const resp = await fetch("https://precollege.sps.columbia.edu/admissions/dates-and-deadlines");
  const html = await resp.text();
  const doc = new DOMParser().parseFromString(html, "text/html");
  // Find all text inside tables or main article
  const tables = Array.from(doc.querySelectorAll('table')).map(t => t.innerText);
  const headings = Array.from(doc.querySelectorAll('h1, h2, h3, h4, p, li')).map(e => e.innerText);
  return { tables, headings: headings.filter(h => h.includes('Deadline') || h.includes('Session') || h.includes('Summer')) };
});
console.log("Columbia dates:", JSON.stringify(datesText, null, 2));

