const tabId = 787784104;
const deadText = await browserjs(tabId, async () => {
  const links = Array.from(document.querySelectorAll('a')).filter(a => a.innerText.includes('Dates & Deadlines'));
  if (links.length) {
    const resp = await fetch(links[0].href);
    const html = await resp.text();
    const doc = new DOMParser().parseFromString(html, "text/html");
    return doc.querySelector('main')?.innerText || doc.body.innerText;
  }
  return "No link found";
});
console.log("Cornell deadlines snippet:\n", deadText.slice(0, 1500));

