  return {
    dates: docDates.querySelector('main')?.innerText.slice(0, 1000) || docDates.body.innerText.slice(0, 1000),
    deadlines: docDeadlines.querySelector('main')?.innerText.slice(0, 1000) || docDeadlines.body.innerText.slice(0, 1000)
  };
});
console.log("Dartmouth dates & deadlines:\n", JSON.stringify(datesInfo, null, 2));

